INSERT OR IGNORE INTO assignments (id, user_id, title, course, description, due, status, score, max, weight, submissions, rubric) VALUES ('a1', '00000000-0000-4000-8000-000000000001', 'Build: REST API assignment', 'Backend & APIs', 'Ship a production-ready REST API in Express with PostgreSQL, auth (JWT + refresh rotation), validation, and a test suite. Follow the starter repo and the acceptance criteria below.', 'Today 23:59', 'submitted', NULL, 100, 25, '[{"file":"api-submission.zip","size":"4.2 MB","uploaded":"Today 18:31"}]', '[{"criterion":"API design & routes","detail":"REST conventions, status codes, error shapes","weight":20},{"criterion":"Auth & security","detail":"JWT rotation, bcrypt, rate limiting","weight":25},{"criterion":"Data layer","detail":"Postgres schema, migrations, indexes","weight":25},{"criterion":"Tests & docs","detail":"Coverage > 70%, README with runbook","weight":15},{"criterion":"Code quality","detail":"Linting, typing, no secrets in repo","weight":15}]');
